def F(x, y, z, a, b, c):
    return abs(x+y-a-b) + abs(y+z-b-c) + abs(z+x-c-a)

queries = [
    (0, 0, 0),
    (9, 9, 9),
    (4, 4, 4)
]

collisions = {}
total_triples = 1000
collision_count = 0

print(f"Testing {total_triples} triples against the query set: {queries}")

for x in range(10):
    for y in range(10):
        for z in range(10):
            triple = (x, y, z)
            results = tuple(F(x, y, z, *q) for q in queries)

            if results not in collisions:
                collisions[results] = []
            collisions[results].append(triple)

# Check for collisions (where a result tuple maps to more than one triple)
for results, triples_list in collisions.items():
    if len(triples_list) > 1:
        collision_count += 1
        # Print a few examples of collisions for analysis
        if collision_count <= 5:
            print(f"Collision found for result {results}: Triples include {triples_list[:3]}...")

print(f"\nTotal number of distinct result sets found: {len(collisions)}")
print(f"Total number of colliding result sets (results leading to > 1 triple): {collision_count}")

